    def parse_order(self, order: dict, market: Market = None) -> Order:
        # override the standard parseOrder to apply OctoBot's MexcCCXTAdapter.fix_order:
        # mexc does not return fee info on canceled orders; synthesize empty fee with currency set to symbol quote
        parsed = super(ob_mexc, self).parse_order(order, market)
        status = self.safe_string_lower(parsed, 'status')
        fee = self.safe_dict(parsed, 'fee')
        if status == 'canceled' and fee is None:
            quoteCcy = self.ob_quote_from_symbol(self.safe_string(parsed, 'symbol', ''))
            feeCurrency = ''
            if quoteCcy is not None:
                feeCurrency = quoteCcy
            parsed['fee'] = {
                'currency': feeCurrency,
                'cost': 0,
            }
        return parsed

    def fetch_deposits(self, code: Str = None, since: Int = None, limit: Int = None, params={}) -> List[Transaction]:
        if since is None:
            now = self.milliseconds()
            # MEXC allows up to 7 days per request when startTime is set
            since = now - 6 * 24 * 60 * 60 * 1000
            params = self.extend(params, {'endTime': now})
        return super(ob_mexc, self).fetch_deposits(code, since, limit, params)

