    def ob_quote_from_symbol(self, symbolStr: Str) -> Str:
        # extract the quote currency from a unified symbol like "BTC/USD" or "BTC/USDT:USDT"
        if symbolStr is None or symbolStr == '':
            return ''
        parts = symbolStr.split('/')
        if len(parts) < 2:
            return ''
        quoteAndSettle = parts[1]
        quoteParts = quoteAndSettle.split(':')
        return quoteParts[0]
